<script setup>
import { ref } from 'vue';
const props=defineProps({modelValue:File,label:String,required:Boolean,error:String});const emit=defineEmits(['update:modelValue']);const input=ref(null);const zone=ref(null);const dragging=ref(false);const focused=ref(false);const localError=ref('');const readableSize=bytes=>bytes?(bytes/1024/1024).toFixed(2)+' MB':'';
const accept=file=>{localError.value='';if(!file)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){localError.value='Dokumen harus berupa file PDF.';return}if(file.size>3*1024*1024){localError.value='Ukuran maksimal setiap dokumen adalah 3 MB.';return}emit('update:modelValue',file)};
const selected=e=>accept(e.target.files?.[0]);const dropped=e=>{dragging.value=false;accept(e.dataTransfer.files?.[0])};const pasted=e=>{const file=[...(e.clipboardData?.files||[])][0];if(file){e.preventDefault();accept(file)}else localError.value='Clipboard tidak berisi file PDF.'};const remove=e=>{e.stopPropagation();emit('update:modelValue',null);if(input.value)input.value.value=''};const activatePaste=()=>zone.value?.focus();const chooseFile=e=>{e.stopPropagation();input.value?.click()};
</script>
<template><div><div class="mb-2 flex items-center justify-between gap-3"><label class="text-sm font-black text-slate-800">{{label}}</label><span class="rounded-full px-2 py-1 text-[9px] font-black" :class="required?'bg-red-50 text-red-700':'bg-slate-100 text-slate-500'">{{required?'WAJIB':'OPSIONAL'}}</span></div><div ref="zone" tabindex="0" role="group" :aria-label="'Area upload '+label+'. Klik lalu paste file, drag and drop, atau gunakan tombol Choose File.'" class="file-drop-input" :class="{'file-drop-active':dragging||focused,'file-drop-filled':modelValue}" @click="activatePaste" @focus="focused=true" @blur="focused=false" @dragenter.prevent="dragging=true" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="dropped" @paste="pasted"><input ref="input" type="file" accept="application/pdf,.pdf" class="hidden" @change="selected"/><div class="grid h-10 w-10 shrink-0 place-items-center rounded-xl" :class="modelValue?'bg-emerald-50 text-emerald-600':'bg-red-50 text-red-600'">{{modelValue?'✓':'+'}}</div><div class="min-w-0 flex-1"><template v-if="modelValue"><p class="truncate text-sm font-bold text-slate-800">{{modelValue.name}}</p><p class="mt-0.5 text-[11px] text-slate-500">{{readableSize(modelValue.size)}} · PDF siap diunggah</p></template><template v-else><p class="text-sm font-semibold text-slate-600"><span class="font-black text-red-600">Klik area ini lalu tekan Ctrl+V</span></p><p class="mt-0.5 text-[11px] text-slate-400">Atau drag & drop · PDF maksimal 3 MB</p></template></div><div class="flex shrink-0 flex-col gap-1.5 sm:flex-row"><button type="button" class="choose-file-button" @click="chooseFile">{{modelValue?'Ganti File':'Choose File'}}</button><button v-if="modelValue" type="button" class="rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold text-slate-600 hover:bg-red-50 hover:text-red-700" @click="remove">Hapus</button></div></div><p v-if="localError||error" class="err">{{localError||error}}</p></div></template>
